from ortools.sat.python import cp_model

def solve_magic_square(n):
    model = cp_model.CpModel()

    # Define the variables
    x = {}
    for i in range(n):
        for j in range(n):
            x[i,j] = model.NewIntVar(0, 2, f'x[{i},{j}]')

    # Constraint: Each row and column should contain equal numbers of I, M, O
    for i in range(n):
        model.Add(sum(x[i,j] for j in range(n)) == n//3 * (0 + 1 + 2))
        model.Add(sum(x[j,i] for j in range(n)) == n//3 * (0 + 1 + 2))

    # Constraint: Diagonal sums when length is multiple of 3
    for d in range(-(n-1), n):
        diag_len = min(min(d+n, n), min(-d+1, n))
        if diag_len % 3 == 0:
            model.Add(sum(x[i, i-d] for i in range(max(0,d), min(n, n+d))) == diag_len // 3 * (0 + 1 + 2))

    # Solve the model
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        solution = [[['I','M','O'][solver.Value(x[i,j])] for j in range(n)] for i in range(n)]
        return solution
    else:
        return None

solution = solve_magic_square(9)
if solution:
    array_str = '\\begin{array}{%s}' % ('c'*9)
    for row in solution:
        array_str += ' & '.join(row) + '\\\\'
    array_str += '\\end{array}'
    print(array_str)
